		if (i) memcpy(pre[i], pre[i - 1], sizeof pre[i]);
		down (j, 2, w[i]) upmax(pre[i][j], pre[i][w[i]] + 1);
	}
	down (i, N, 0) {
		if (i < N - 1) memcpy(suf[i], suf[i + 1], sizeof suf[i]);
		rep (j, 0, w[i] + 1) upmax(suf[i][j], suf[i][w[i]] + 1);
	}
