ll pow1(ll k, ll st) {
	ll ans = 1;
	while (st) {
		if (st & 1) ans = mdd(ans * k);
		k = mdd(k * k);
		st >>= 1;
	}
	re ans;
}

ll get_sum(ll n) {
	n %= mod;
	n += mod;
	n %= mod;
	re (n * (n + 1) / 2LL) % mod;
}

ll get_cnt(ll a) {
	a = mdd(a);
	re mdd(mdd(2LL * mdd(a * a) * a) - mdd(3LL * mdd(a * a) * mdd(n + 2)) + mdd(mdd(a) * mdd(3LL * n + 4)) + mdd(n) * mdd(mdd(mdd(n) * mdd(n)) + 3LL * n + 2LL));
}

